mapper.select:
SELECT Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop
FROM RSWS_TempMonitor_Copy
WHERE Workshop = #{workshop}

    AND UpdateTime >= #{startTime}


    AND UpdateTime <= #{endTime}


    AND DeviceID LIKE CONCAT('%', #{deviceId}, '%')


    AND Name LIKE CONCAT('%', #{name}, '%')

ORDER BY UpdateTime DESC

WITH LatestDeviceData AS ( SELECT Name, ElectricEnergy, ROW_NUMBER() OVER (PARTITION BY Name ORDER BY UpdateTime DESC) as rn FROM RSWS_TempMonitor_Copy WHERE Workshop = #{workshop} AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) SELECT SUM(ElectricEnergy) as totalElectricEnergy, COUNT(DISTINCT Name) as totalDevices FROM LatestDeviceData WHERE rn = 1

SELECT Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop
FROM RSWS_TempMonitor_Copy
WHERE Workshop = #{workshop}
AND ElectricEnergy IS NOT NULL

    AND UpdateTime >= #{startTime}


    AND UpdateTime <= #{endTime}

ORDER BY Name, UpdateTime DESC

SELECT Id, DeviceID, Name, Tem, Hum, MAC, UpdateTime, ElectricEnergy, NodeID, Workshop FROM RSWS_TempMonitor_Copy WHERE ( (Workshop = '105_无压烧结' AND Name IN ('105_无压烧结_1#', '105_无压烧结_2#')) OR (Workshop = '112_终检' AND Name IN ('112_终检_1#', '112_终检_2#')) OR (Workshop = '101_配料' AND Name IN ('101_配料_1#', '101_配料_2#')) ) AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
ORDER BY Name, UpdateTime DESC

choose.when:
WITH DailyBoundaries AS ( SELECT DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayStart, DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)), CAST( #{startTime} DATEADD(DAY, -7, GETDATE()) AS DATE) ) as DayEnd FROM ( SELECT TOP ( DATEDIFF(DAY, #{startTime} DATEADD(DAY, -7, GETDATE()), #{endTime} GETDATE() ) + 1 ) 1 as DummyColumn FROM sys.objects ) dummy ), DeviceDailyData AS ( SELECT DayStart, SUM( CASE WHEN tm_start.ElectricEnergy IS NOT NULL THEN tm_start.ElectricEnergy ELSE 0 END ) as StartEnergy, SUM( CASE WHEN tm_end.ElectricEnergy IS NOT NULL THEN tm_end.ElectricEnergy ELSE 0 END ) as EndEnergy FROM DailyBoundaries db CROSS JOIN ( SELECT DISTINCT DeviceID, Name, Workshop FROM RSWS_TempMonitor_Copy WHERE Workshop = #{workshop} AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) devices LEFT JOIN RSWS_TempMonitor_Copy tm_start ON ( tm_start.DeviceID = devices.DeviceID AND tm_start.Name = devices.Name AND tm_start.Workshop = #{workshop} AND tm_start.ElectricEnergy IS NOT NULL AND tm_start.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = #{workshop} AND inner_tm.UpdateTime >= db.DayStart AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) LEFT JOIN RSWS_TempMonitor_Copy tm_end ON ( tm_end.DeviceID = devices.DeviceID AND tm_end.Name = devices.Name AND tm_end.Workshop = #{workshop} AND tm_end.ElectricEnergy IS NOT NULL AND tm_end.UpdateTime = ( SELECT TOP 1 UpdateTime FROM RSWS_TempMonitor_Copy inner_tm WHERE inner_tm.DeviceID = devices.DeviceID AND inner_tm.Name = devices.Name AND inner_tm.Workshop = #{workshop} AND inner_tm.UpdateTime >= db.DayEnd AND inner_tm.ElectricEnergy IS NOT NULL ORDER BY inner_tm.UpdateTime ASC ) ) GROUP BY DayStart ) SELECT COALESCE(SUM( CASE WHEN StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL AND EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END ), 0) AS totalConsumption FROM DeviceDailyData WHERE StartEnergy IS NOT NULL AND EndEnergy IS NOT NULL

choose.otherwise:
WITH DeviceEnergy AS ( SELECT DeviceID, Name, FIRST_VALUE(ElectricEnergy) OVER (PARTITION BY DeviceID, Name ORDER BY UpdateTime ASC) AS StartEnergy, FIRST_VALUE(ElectricEnergy) OVER (PARTITION BY DeviceID, Name ORDER BY UpdateTime DESC) AS EndEnergy, ROW_NUMBER() OVER (PARTITION BY DeviceID, Name ORDER BY UpdateTime ASC) AS rn FROM RSWS_TempMonitor_Copy WHERE Workshop = #{workshop} AND ElectricEnergy IS NOT NULL
AND UpdateTime >= #{startTime}
AND UpdateTime <= #{endTime}
) SELECT COALESCE(SUM( CASE WHEN EndEnergy >= StartEnergy THEN EndEnergy - StartEnergy ELSE 0 END ), 0) AS totalConsumption FROM DeviceEnergy WHERE rn = 1
